PAGE = dict(
    slug='z_label_gap',
    title='Pane::z_label_gap',
    signature='Pane& Pane::z_label_gap(double points)\nPane& Pane::clear_z_label_gap() noexcept',
    intro='Sets the gap, in drawing units, between the z axis (and its tick labels) and the axis label. The setting is stored in `z_axis().label_gap` as an optional value: empty until a gap is set, which means the renderer chooses a gap from the font size. `z_label_gap` stores an explicit gap and `clear_z_label_gap()` removes it, restoring the automatic choice, so a figure that sets and then clears a gap is exactly the figure that never set one.\n\nThe gap must be finite and not negative. Anything else (a negative number, infinity or NaN) is refused with `pluss::Error`, the stored value is left as it was, and zero is valid and puts the two elements as close as the renderer allows. The gap is read when the figure is rendered. It is per axis: the other axes keep their own.',
    parameters='**points** (`double`)\n    The gap in drawing units. Finite and not negative.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='readback', text='Default, set, clear. A new pane has no override (`label_gap` is empty); the call stores the value and `clear_z_label_gap()` removes it again.',
             code='auto fig = studio("z_label_gap_readback");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\nauto show = [&] { const auto& v = pane.z_axis().label_gap; std::cout << (v ? std::to_string(*v) : std::string("none")) << "\\n"; };\nstd::cout << "new pane: "; show();\npane.z_label_gap(24.0);\nstd::cout << "after z_label_gap(24): "; show();\npane.clear_z_label_gap();\nstd::cout << "after clear_z_label_gap(): "; show();\nfig.save_svg("figure.svg");'),
        dict(id='effect', text='The effect. With a label set, a gap of 0, 14 and 60 gives three different figures; the saved figure uses 60, which pushes the z label well away from the axis.',
             code='auto build = [&](double gap) {\n  auto fig = studio("z_label_gap_effect");\n  auto& pane = fig.pane3("p");\n  pane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\n  pane.z_label("Axis label");\n  pane.z_label_gap(gap);\n  return fig;\n};\nstd::cout << "0 vs 14: " << (build(0.0).to_svg() != build(14.0).to_svg()) << ", 14 vs 60: " << (build(14.0).to_svg() != build(60.0).to_svg()) << "\\n";\nbuild(60.0).save_svg("figure.svg");'),
        dict(id='clear_restores', text='Clearing restores the default exactly. After `clear_z_label_gap()` the figure equals the one that never set a gap.',
             code='auto build = [&](bool set_then_clear) {\n  auto fig = studio("z_label_gap_clear");\n  auto& pane = fig.pane3("p");\n  pane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\n  pane.z_label("Axis label");\n  if (set_then_clear) pane.z_label_gap(40.0).clear_z_label_gap();\n  return fig.to_svg();\n};\nstd::cout << "equal: " << (build(true) == build(false)) << "\\n";\nauto fig = studio("z_label_gap_clear_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\npane.z_label("Axis label");\nfig.save_svg("figure.svg");'),
        dict(id='invalid', text='Invalid gaps are refused and the stored value is kept. A negative number, infinity and NaN throw `pluss::Error`; zero is a valid gap.',
             code='auto fig = studio("z_label_gap_invalid");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0, 1, 0, 1}, std::vector<double>{0, 1, 2, 3});\npane.z_label("Axis label");\npane.z_label_gap(10.0);\nfor (double bad : {-1.0, std::numeric_limits<double>::infinity(), std::numeric_limits<double>::quiet_NaN()}) {\n  try {\n    pane.z_label_gap(bad);\n  } catch (const pluss::Error& e) {\n    std::cout << bad << ": " << e.message() << "\\n";\n  }\n}\npane.z_label_gap(0.0);\nstd::cout << "zero accepted: " << *pane.z_axis().label_gap << "\\n";\npane.z_label_gap(10.0);\nstd::cout << "kept after errors: " << *pane.z_axis().label_gap << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- `z_label_gap` throws, so it is not `noexcept`; `clear_z_label_gap` never throws.\n- The related gap for the other element is [`z_tick_label_gap`](z_tick_label_gap.md).',
    see=['[`Pane::z_label`](z_label.md): the label the gap is measured to.', '[`Pane::z_tick_label_gap`](z_tick_label_gap.md): the other gap.', '[`Pane::x_label_gap`](x_label_gap.md): the same setting for the x axis.', '[`Pane::y_label_gap`](y_label_gap.md): the same setting for the y axis.'],
)
